            residuals = prices - np.tile([beta, intercept], (len(prices), 1))
            z_scores = (residuals - residuals.mean(axis=0)) / residuals.std(axis=0)

            long = None
            short = None
            for ticker, z in pair.z_scores.items():
                if abs(z) > 2.0:
                    if z > 0:
                        long = ticker
                    else:
                        short = ticker

            if not long or not short:
                continue

            weight = 0.5
            if self.portfolio[long].holding_quantity == 0:
                self.set_holdings(long, weight)
            if self.portfolio[short].holding_quantity == 0:
                self.set_holdings(short, -weight)

    def _get_pair(self, security: Equity) -> tuple[EdgeLinearRegressionModel, list['TradeBar']]:
        pair = self.objects.get(security.id)
        if not pair:
            pair = self.add_pair(security, "KO-PEP")
            self.set_holdings(pair.long, 1)
            self.set_holdings(pair.short, -1)
        return pair

    class EdgeLinearRegressionModel(scipy.stats.linregress):
        def __init__(self) -> None:
